# Initially generated by GitHub Copilot.
"""Repo maintenance: clean .novc/, check formatting, lint, run the test suite,
run the routine rebuild.

Run from the repo root (each step resolves paths via ``mb_cmn.paths.repo_root()``):

    .venv/Scripts/python.exe py/main_repo_maintenance.py
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-novc
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-black
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-lint
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-tests
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-rebuild
    .venv/Scripts/python.exe py/main_repo_maintenance.py --continue-on-test-failure

Five independent steps, in order:

1. Wipe the gitignored ``.novc/`` scratch dir. Everything in it is a
   regenerable download cache or tool output, never a durable result.
2. Run ``black --check py``. Check-only: drift is reported, never
   auto-reformatted -- repo-wide reformatting is its own deliberate commit
   (see ``py/main_repo_util.py --run-black``). Failures set the overall exit
   status but do not block the later steps.
3. Run ``ruff check py`` (the linter, configured by ``ruff.toml``). Like
   black, lint failures set the overall exit status but do not block the
   later steps.
4. Run ``py/main_test.py``, this repo's canonical test entrypoint (see
   CLAUDE.md) -- a ``pytest.main()`` wrapper over the whole ``py/tests`` tree.
5. Run ``py/main_0_mega.py``, the routine downstream rebuild -- every
   parameterless, non-download rebuild step (parse, mam-with-doc,
   tmpl-survey, mam-simple, mam4sef/ajf, mam-osis, letter-small-job,
   decnreub, multimark, wordlist, explicit-xataf, and the authored docs).

The rebuild step is skipped if the test step failed, unless
``--continue-on-test-failure`` is given.
"""

import argparse
import shutil
import subprocess
import sys

from mb_cmn import paths

_REPO = paths.repo_root()
_NOVC = _REPO / ".novc"


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--skip-novc", action="store_true", help="don't clean .novc/")
    parser.add_argument(
        "--skip-black", action="store_true", help="don't run black --check"
    )
    parser.add_argument("--skip-lint", action="store_true", help="don't run ruff")
    parser.add_argument(
        "--skip-tests", action="store_true", help="don't run the test suite"
    )
    parser.add_argument(
        "--skip-rebuild", action="store_true", help="don't run py/main_0_mega.py"
    )
    parser.add_argument(
        "--continue-on-test-failure",
        action="store_true",
        help="run the rebuild step even if a test failed",
    )
    return parser.parse_args()


def clean_novc() -> None:
    if not _NOVC.exists():
        print(".novc: nothing to clean (directory does not exist)")
        return
    removed = sorted(p.name for p in _NOVC.iterdir())
    shutil.rmtree(_NOVC)
    _NOVC.mkdir()
    if removed:
        print(f".novc: removed {len(removed)} entries: {', '.join(removed)}")
    else:
        print(".novc: already empty")


def run_black() -> bool:
    result = subprocess.run([sys.executable, "-m", "black", "--check", "py"], cwd=_REPO)
    ok = result.returncode == 0
    print(f"black: {'OK' if ok else f'FAILED (exit {result.returncode})'}")
    return ok


def run_lint() -> bool:
    result = subprocess.run([sys.executable, "-m", "ruff", "check", "py"], cwd=_REPO)
    ok = result.returncode == 0
    print(f"lint: {'OK' if ok else f'FAILED (exit {result.returncode})'}")
    return ok


def run_tests() -> bool:
    result = subprocess.run([sys.executable, "py/main_test.py"], cwd=_REPO)
    ok = result.returncode == 0
    print(f"tests: {'OK' if ok else f'FAILED (exit {result.returncode})'}")
    return ok


def run_rebuild() -> bool:
    script = _REPO / "py" / "main_0_mega.py"
    result = subprocess.run([sys.executable, str(script)], cwd=_REPO)
    print(
        "rebuild: OK"
        if result.returncode == 0
        else f"rebuild: FAILED (exit {result.returncode})"
    )
    return result.returncode == 0


def main() -> None:
    sys.stdout.reconfigure(encoding="utf-8", line_buffering=True)
    sys.stderr.reconfigure(encoding="utf-8")
    args = _parse_args()
    ok = True
    tests_ok = True

    if not args.skip_novc:
        clean_novc()

    if not args.skip_black:
        ok = run_black() and ok

    if not args.skip_lint:
        ok = run_lint() and ok

    if not args.skip_tests:
        tests_ok = run_tests()
        ok = tests_ok and ok

    if not args.skip_rebuild:
        if tests_ok or args.continue_on_test_failure:
            ok = run_rebuild() and ok
        else:
            print(
                "rebuild: skipped (tests failed; pass --continue-on-test-failure "
                "to run anyway)"
            )
            ok = False

    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
